//! Regression tests for code generated by the derive macros.

// Shadow common prelude items to check the generated code doesn't depend on them.
#[allow(dead_code)]
type Result<T> = std::result::Result<T, ()>;
#[allow(dead_code)]
type Option = u8;

use measured::{
    Counter, FixedCardinalityLabel, LabelGroup, MetricGroup, metric::MetricFamilyEncoding,
};
use measured_prometheus_text::BufferedTextEncoder;

#[derive(FixedCardinalityLabel, Clone, Copy)]
enum Method {
    Get,
    Post,
}

#[derive(LabelGroup)]
#[label(set = RequestLabelSet)]
struct RequestLabels {
    #[label(rename = "foo")]
    a: Method,
    #[label(rename = "FOO")]
    b: Method,
}

#[derive(MetricGroup)]
#[metric(new())]
struct Metrics {
    /// counts things
    #[doc(hidden)]
    #[metric(rename = "foo")]
    a: Counter,
    #[metric(rename = "FOO")]
    b: Counter,
    requests: measured::CounterVec<RequestLabelSet>,
}

#[test]
fn shadowed_prelude_and_similar_names() {
    let metrics = Metrics::new();
    metrics.a.inc();
    metrics.b.inc_by(2);
    metrics.requests.inc(RequestLabels {
        a: Method::Get,
        b: Method::Post,
    });

    let mut enc = BufferedTextEncoder::new();
    metrics.collect_group_into(&mut enc).unwrap();
    let s = String::from_utf8(enc.finish().to_vec()).unwrap();

    assert_eq!(
        s,
        r#"# HELP foo counts things
# TYPE foo counter
foo 1

# TYPE FOO counter
FOO 2

# TYPE requests counter
requests{foo="get",FOO="post"} 1
"#
    );
}

/// A label set with a fixed vocabulary, usable as either a fixed or dynamic set.
struct Words(&'static [&'static str]);

impl measured::label::LabelSet for Words {
    type Value<'a> = &'a str;

    fn dynamic_cardinality(&self) -> std::option::Option<usize> {
        Some(self.0.len())
    }

    fn encode(&self, value: &str) -> std::option::Option<usize> {
        self.0.iter().position(|w| *w == value)
    }

    fn decode(&self, value: usize) -> &str {
        self.0[value]
    }
}

impl measured::label::FixedCardinalitySet for Words {}
impl measured::label::DynamicLabelSet for Words {}

#[derive(LabelGroup)]
#[label(set = PairLabelSet)]
struct PairLabels<'a> {
    #[label(fixed_with = Words)]
    fixed: &'a str,
    #[label(dynamic_with = Words)]
    dynamic: &'a str,
}

#[test]
fn label_set_new_uses_declaration_order() {
    let set = PairLabelSet::new(Words(&["f"]), Words(&["d"]));
    let counter = measured::CounterVec::with_label_set(set);
    counter.inc(PairLabels {
        fixed: "f",
        dynamic: "d",
    });

    let mut enc = BufferedTextEncoder::new();
    counter
        .collect_family_into(
            measured::metric::name::MetricName::from_str("pairs"),
            None,
            &mut enc,
        )
        .unwrap();
    let s = String::from_utf8(enc.finish().to_vec()).unwrap();
    assert!(s.contains("pairs{fixed=\"f\",dynamic=\"d\"} 1\n"), "{s}");
}

#[derive(LabelGroup)]
#[label(set = RawLabelSet)]
struct RawLabels {
    r#type: Method,
}

#[derive(MetricGroup)]
#[metric(new())]
struct RawMetrics {
    r#in_flight: measured::CounterVec<RawLabelSet>,
}

#[test]
fn raw_identifiers() {
    let metrics = RawMetrics::new();
    metrics.r#in_flight.inc(RawLabels {
        r#type: Method::Get,
    });

    let mut enc = BufferedTextEncoder::new();
    metrics.collect_group_into(&mut enc).unwrap();
    let s = String::from_utf8(enc.finish().to_vec()).unwrap();
    assert!(s.contains("in_flight{type=\"get\"} 1\n"), "{s}");
}
